import sqlite3

db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE customer(id INT, name TEXT, phone TEXT, grade TEXT);
INSERT INTO customer VALUES (1,'김토스','010-1234-5678','VIP'),(2,'이뱅크','010-9999-0000','일반');
""")

BLOCKED = {("customer", "name"), ("customer", "phone")}   # 에이전트에게 닫힌 칸

def guard(action, table, column, *_):
    if action == sqlite3.SQLITE_READ and (table, column) in BLOCKED:
        return sqlite3.SQLITE_DENY
    return sqlite3.SQLITE_OK

db.set_authorizer(guard)   # LLM 이 만든 SQL 은 이 문 뒤에서만 돈다

for sql in ["SELECT grade, COUNT(*) FROM customer GROUP BY grade",
            "SELECT name, phone FROM customer WHERE grade='VIP'"]:
    try:
        print("OK  ", db.execute(sql).fetchall())
    except sqlite3.DatabaseError as e:
        print("막힘", sql, "→", e)
# 출력
# OK   [('VIP', 1), ('일반', 1)]
# 막힘 SELECT name, phone FROM customer WHERE grade='VIP' → access to customer.name is prohibited
